  window.__wxExport = {
    download: dl,
    toFmt: toFmt,
    model3d: function (fmt, name) {
      if (!window.Wx3D || !window.Wx3D.captureView) return;
      var u = window.Wx3D.captureView("front", 1100);
      if (!u) return;
      toFmt(u, fmt).then(function (out) { dl(out, (name || "3D建模图") + ext(fmt)); });
    },
    three: function (fmt, name) {
      if (!window.Wx3D || !window.Wx3D.captureThreeViews) return Promise.resolve();
      return window.Wx3D.captureThreeViews(900).then(function (u) {
        if (!u) return;
        return toFmt(u, fmt).then(function (out) { dl(out, (name || "三视图") + ext(fmt)); });
      });
    },
    interactive: function (name) {
      if (!window.Wx3D || !window.Wx3D.exportScene) return Promise.resolve(false);
      var data = window.Wx3D.exportScene();
      if (!data || !data.json) return Promise.resolve(false);
      return fetch("./assets/three.min.js").then(function (r) { return r.text(); }).then(function (threeSrc) {
        // SVG dataUrl 先在内存里转 PNG，保证导出 HTML 里 TextureLoader 稳定加载
        return new Promise(function (resolve) {
          if (!data.artUrl || data.artUrl.indexOf("data:image/svg") !== 0) return resolve(data.artUrl);
          var im = new Image();
          im.onload = function () {
            try {
              var c = document.createElement("canvas");
              c.width = 1024; c.height = 1024;
              var x = c.getContext("2d");
              x.fillStyle = "#ffffff"; x.fillRect(0, 0, 1024, 1024);
              x.drawImage(im, 0, 0, 1024, 1024);
              resolve(c.toDataURL("image/png"));
            } catch (e) { resolve(data.artUrl); }
          };
          im.onerror = function () { resolve(data.artUrl); };
          im.src = data.artUrl;
        }).then(function (artPng) {
          var html = buildInteractiveHTML(threeSrc, data, artPng, name || "纹现-可交互3D");
          var blob = new Blob([html], { type: "text/html;charset=utf-8" });
          var url = URL.createObjectURL(blob);
          dl(url, (name || "纹现-可交互3D") + ".html");
          setTimeout(function () { URL.revokeObjectURL(url); }, 60000);
          return true;
        });
      }).catch(function (e) { console.error("[export interactive]", e); return false; });
    }
  };
